SELECT 'AR' AS ledger,COALESCE(SUM(CASE WHEN i.status!='PAID' THEN i.total ELSE 0 END),0) AS open_amount FROM invoice i WHERE i.generation_run_id IN (:actual_run_id,:generation_run_id) UNION ALL SELECT 'AP',COALESCE(SUM(vb.amount),0)-COALESCE((SELECT SUM(amount) FROM vendor_payment WHERE generation_run_id IN (:actual_run_id,:generation_run_id)),0) FROM vendor_bill vb WHERE vb.generation_run_id IN (:actual_run_id,:generation_run_id);
